+    // Write encrypted seed bytes under key ("walletseedckey", seed_pubkey)
+    if (!WriteIC(std::make_pair(DBKeys::WALLETSEEDCKEY, seed_pubkey), crypted_secret, /*fOverwrite=*/false)) {
